-- NavApp Tilemaker Lua profile (OpenMapTiles-compatible + Nature Reserves Fix + Enrichment Lookup)
-- References: devops/docs/tilemaker-nature-reserves-fix.md & devops/docs/osm-zoom-levels.md

node_keys = { "place", "natural", "amenity", "tourism", "historic", "leisure", "shop", "waterway", "highway" }
way_keys = { "highway", "railway", "waterway", "natural", "landuse", "leisure", "boundary", "building", "aeroway", "route", "power", "barrier", "man_made" }

-- Load optional enrichment lookup generated by pbfTagInjector.ts
local enrichment = { ways = {}, refs = {} }
for _, candidate in ipairs({ "enrichment_lookup.lua", "workspace/enrichment_lookup.lua" }) do
  local ok, loaded = pcall(dofile, candidate)
  if ok and type(loaded) == "table" then
    enrichment = loaded
    break
  end
end

local function setMinZoomByArea(minZoom)
  local area = Area()
  if area > 100000000 then MinZoom(math.max(minZoom, 4))
  elseif area > 10000000 then MinZoom(math.max(minZoom, 6))
  elseif area > 1000000 then MinZoom(math.max(minZoom, 8))
  else MinZoom(math.max(minZoom, 9)) end
end

local function setNameAttrs()
  local name = Find("name")
  local nameHe = Find("name:he")
  local nameEn = Find("name:en")
  if name ~= "" then
    Attribute("name", name)
    Attribute("name:latin", nameEn ~= "" and nameEn or name)
  elseif nameEn ~= "" then
    Attribute("name", nameEn)
    Attribute("name:latin", nameEn)
  elseif nameHe ~= "" then
    Attribute("name", nameHe)
    Attribute("name:latin", nameHe)
  end
  if nameHe ~= "" then Attribute("name:he", nameHe) end
  if nameEn ~= "" then Attribute("name:en", nameEn) end
end

local function classifyPark(boundary, leisure, protectClass, protectionTitle)
  local pt = string.lower(protectionTitle or "")
  if protectClass == "98" then return nil end
  if protectClass == "2" or string.find(pt, "national park", 1, true) then
    return "national_park"
  end
  if leisure == "nature_reserve" or protectClass == "1" or protectClass == "1a" or protectClass == "1b"
     or protectClass == "3" or protectClass == "4" or protectClass == "5" or protectClass == "6"
     or string.find(pt, "nature reserve", 1, true) or string.find(pt, "forest reserve", 1, true)
     or string.find(pt, "biosphere", 1, true) or string.find(pt, "marine park", 1, true) then
    return "nature_reserve"
  end
  if boundary == "protected_area" then
    if protectClass == "22" or string.find(pt, "monument", 1, true) then
      return "nature_reserve"
    end
    if Find("name") ~= "" or Find("name:he") ~= "" then
      return "nature_reserve"
    end
  end
  return nil
end

function init_function()
end

function exit_function()
end

function relation_scan_function()
  local relType = Find("type")
  local boundary = Find("boundary")
  local route = Find("route")
  if relType == "boundary" and (boundary == "administrative" or boundary == "protected_area") then
    Accept()
  elseif relType == "route" and (route == "hiking" or route == "foot" or route == "bicycle" or route == "mtb" or route == "4wd" or route == "horse") then
    Accept()
  end
end

function node_function()
  local place = Find("place")
  if place ~= "" then
    Layer("place", false)
    Attribute("class", place)
    setNameAttrs()
    if place == "country" then MinZoom(1)
    elseif place == "city" then MinZoom(4)
    elseif place == "town" then MinZoom(7)
    elseif place == "village" then MinZoom(10)
    else MinZoom(12) end
  end

  local natural = Find("natural")
  if natural == "peak" or natural == "saddle" then
    Layer("mountain_peak", false)
    Attribute("class", natural)
    setNameAttrs()
    local ele = tonumber(Find("ele"))
    if ele then AttributeNumeric("ele", ele) end
    MinZoom(10)
    return
  end

  local amenity = Find("amenity")
  local tourism = Find("tourism")
  local historic = Find("historic")
  local leisure = Find("leisure")
  if natural == "spring" or natural == "cave_entrance" or amenity ~= "" or tourism ~= "" or historic ~= "" or leisure ~= "" then
    Layer("poi", false)
    local cls = amenity ~= "" and amenity or (tourism ~= "" and tourism or (historic ~= "" and historic or (leisure ~= "" and leisure or natural)))
    Attribute("class", cls)
    Attribute("subclass", cls)
    setNameAttrs()
    MinZoom(12)
  end
end

function way_function()
  local highway = Find("highway")
  local railway = Find("railway")
  local waterway = Find("waterway")
  local natural = Find("natural")
  local landuse = Find("landuse")
  local leisure = Find("leisure")
  local boundary = Find("boundary")
  local building = Find("building")
  local aeroway = Find("aeroway")

  -- 1. Protected areas / Parks (closed ways & multipolygons)
  if boundary == "protected_area" or leisure == "nature_reserve" then
    local parkClass = classifyPark(boundary, leisure, Find("protect_class"), Find("protection_title"))
    if parkClass ~= nil and IsClosed() then
      Layer("park", true)
      Attribute("class", parkClass)
      setNameAttrs()
      setMinZoomByArea(4)
    end
  end

  -- 2. Administrative boundaries (guarded NextRelation loop per tilemaker-nature-reserves-fix.md)
  local isAdminBoundary = (boundary == "administrative")
  local adminLevel = tonumber(Find("admin_level")) or 11
  local routeColour = Find("colour")
  local routeOsmc = Find("osmc:symbol")
  local routeRef = Find("ref")
  local routeNetwork = Find("network")

  while true do
    local rel = NextRelation()
    if not rel then break end
    if FindInRelation("boundary") == "administrative" then
      isAdminBoundary = true
      local relAdmin = tonumber(FindInRelation("admin_level"))
      if relAdmin and relAdmin < adminLevel then
        adminLevel = relAdmin
      end
    elseif FindInRelation("type") == "route" then
      if routeColour == "" then routeColour = FindInRelation("colour") end
      if routeOsmc == "" then routeOsmc = FindInRelation("osmc:symbol") end
      if routeRef == "" then routeRef = FindInRelation("ref") end
      if routeNetwork == "" then routeNetwork = FindInRelation("network") end
    end
  end

  if isAdminBoundary then
    Layer("boundary", false)
    AttributeNumeric("admin_level", adminLevel)
    MinZoom(adminLevel <= 2 and 0 or 6)
  end

  -- 3. Transportation (Roads, Tracks, Paths, Railways) + Enrichment Injection
  if highway ~= "" or railway == "rail" or railway == "light_rail" then
    Layer("transportation", false)
    local cls = "minor"
    local mz = 12
    if railway ~= "" then cls = "rail"; mz = 8
    elseif highway == "motorway" or highway == "motorway_link" then cls = "motorway"; mz = 4
    elseif highway == "trunk" or highway == "trunk_link" then cls = "trunk"; mz = 4
    elseif highway == "primary" or highway == "primary_link" then cls = "primary"; mz = 4
    elseif highway == "secondary" or highway == "secondary_link" then cls = "secondary"; mz = 9
    elseif highway == "tertiary" or highway == "tertiary_link" then cls = "tertiary"; mz = 11
    elseif highway == "track" then cls = "track"; mz = 12
    elseif highway == "path" or highway == "footway" or highway == "pedestrian" or highway == "steps" then cls = "path"; mz = 13
    elseif highway == "cycleway" then cls = "cycleway"; mz = 13
    end
    Attribute("class", cls)
    Attribute("subclass", highway ~= "" and highway or railway)
    if Find("tracktype") ~= "" then Attribute("tracktype", Find("tracktype")) end
    if Find("surface") ~= "" then Attribute("surface", Find("surface")) end
    if Find("sac_scale") ~= "" then Attribute("sac_scale", Find("sac_scale")) end

    -- Apply enrichment lookup by way ID or SPNI ref
    local wayIdStr = tostring(Id())
    local e = enrichment.ways[wayIdStr]
    if not e and routeRef ~= "" then
      e = enrichment.refs[routeRef]
    end
    if e then
      if routeColour == "" and e.colour then routeColour = e.colour end
      if routeOsmc == "" and e.osmc_symbol then routeOsmc = e.osmc_symbol end
      if routeRef == "" and e.ref then routeRef = e.ref end
      if e.description then Attribute("navapp_description", e.description) end
      if e.hazard then Attribute("navapp_hazard", e.hazard) end
      if e.activities then Attribute("navapp_activities", e.activities) end
    end

    if routeColour ~= "" then Attribute("colour", routeColour); mz = math.min(mz, 4) end
    if routeOsmc ~= "" then Attribute("osmc_symbol", routeOsmc); mz = math.min(mz, 4) end
    if routeRef ~= "" then Attribute("ref", routeRef) end
    if routeNetwork ~= "" then Attribute("network", routeNetwork) end
    MinZoom(mz)

    if Find("name") ~= "" or Find("name:he") ~= "" or routeRef ~= "" then
      Layer("transportation_name", false)
      Attribute("class", cls)
      if routeRef ~= "" then Attribute("ref", routeRef) end
      setNameAttrs()
      MinZoom(11)
    end
  end

  -- 4. Water & Waterways
  local intermittent = string.lower(Find("intermittent"))
  local isIntermittent = (intermittent == "yes" or intermittent == "1" or intermittent == "true")
  if natural == "water" or waterway == "riverbank" then
    if IsClosed() then
      Layer("water", true)
      Attribute("class", Find("water") ~= "" and Find("water") or "lake")
      if isIntermittent then AttributeNumeric("intermittent", 1) end
      MinZoom(6)
    end
  elseif waterway ~= "" then
    Layer("waterway", false)
    Attribute("class", waterway)
    if isIntermittent then AttributeNumeric("intermittent", 1) end
    setNameAttrs()
    MinZoom(waterway == "river" and 8 or 12)
  end

  -- 5. Landcover & Landuse
  if natural == "wood" or landuse == "forest" then
    if IsClosed() then Layer("landcover", true); Attribute("class", "wood"); MinZoom(6) end
  elseif natural == "sand" or natural == "beach" then
    if IsClosed() then Layer("landcover", true); Attribute("class", "sand"); MinZoom(6) end
  elseif natural == "wetland" then
    if IsClosed() then Layer("landcover", true); Attribute("class", "wetland"); MinZoom(6) end
  elseif landuse ~= "" and IsClosed() then
    Layer("landuse", true)
    Attribute("class", landuse)
    MinZoom(landuse == "residential" and 4 or 11)
  end

  -- 6. Buildings & Aeroway
  if building ~= "" and IsClosed() then
    Layer("building", true)
    MinZoom(13)
  end
  if aeroway ~= "" then
    Layer("aeroway", IsClosed())
    Attribute("class", aeroway)
    MinZoom(11)
  end
end

function relation_function()
  local relType = Find("type")
  local boundary = Find("boundary")
  if relType == "boundary" and boundary == "protected_area" then
    local parkClass = classifyPark(boundary, Find("leisure"), Find("protect_class"), Find("protection_title"))
    if parkClass ~= nil then
      Layer("park", true)
      Attribute("class", parkClass)
      setNameAttrs()
      setMinZoomByArea(4)
    end
  end
end
